/**
 * One-off importer: reads the live Devbhoomi Realtors checkout and writes
 * site/real-estate/listings.mjs plus the listing images the cards need.
 *
 *   node tools/import-devbhoomi.mjs <path to Devbhoomi-realtors checkout> [--videos]
 *
 * Source of truth is the host's stats/data.json and each listing page. Nothing
 * is invented: a fact the host does not publish stays "To confirm".
 * Re-running overwrites the generated file, so edit the host, not the output.
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const host = process.argv[2];
const withVideos = process.argv.includes('--videos');
if (!host || !fs.existsSync(path.join(host, 'stats/data.json'))) {
  console.error('Usage: node tools/import-devbhoomi.mjs <Devbhoomi-realtors checkout> [--videos]');
  process.exit(1);
}
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const outAssets = path.join(root, 'site/real-estate/assets/listings');
fs.mkdirSync(outAssets, {recursive: true});

const raw = JSON.parse(fs.readFileSync(path.join(host, 'stats/data.json'), 'utf8'));
const records = Array.isArray(raw) ? raw : raw.listings;

const decode = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
const text = html => decode(html.replace(/<svg[\s\S]*?<\/svg>/g, '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const AREA = {'devprayag': 'devprayag', 'pauri-garhwal': 'pauri', 'kholachauri-corridor': 'kholachauri', 'kholachauri': 'kholachauri', 'dehradun-valley': 'dehradun'};
const copied = new Set();
const copy = relative => {
  const src = path.join(host, relative.replace(/^(\.\.\/)+/, ''));
  if (!fs.existsSync(src)) return null;
  const name = path.basename(src);
  const kind = relative.includes('/posters/') ? 'poster-' : '';
  const dest = path.join(outAssets, kind + name);
  if (!copied.has(dest)) { fs.copyFileSync(src, dest); copied.add(dest); }
  return kind + name;
};

const out = [];
for (const r of records) {
  const page = fs.readFileSync(path.join(host, 'properties', r.slug, 'index.html'), 'utf8');
  const main = (page.match(/<main[\s\S]*?<\/main>/) || [''])[0];
  const prose = (main.match(/<div class="prose"[^>]*>([\s\S]*?)<\/div>/) || ['', ''])[1];
  const body = [...prose.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/g)].map(m => text(m[1])).filter(Boolean);
  const highlights = [...((main.match(/<ul class="highlights"[^>]*>([\s\S]*?)<\/ul>/) || ['', ''])[1]).matchAll(/<li[^>]*>([\s\S]*?)<\/li>/g)].map(m => text(m[1])).filter(Boolean);
  const spec = Object.fromEntries([...main.matchAll(/<dt>([\s\S]*?)<\/dt>\s*<dd>([\s\S]*?)<\/dd>/g)].map(m => [text(m[1]), text(m[2])]));
  const gallery = (main.match(/<div class="gallery"[\s\S]*?<h2/) || [''])[0];
  const images = [...new Set([...gallery.matchAll(/(?:src|poster)="([^"]*assets\/img\/(?:listings|posters)\/[^"]+\.jpg)"/g)].map(m => m[1]))];
  const videos = [...new Set([...gallery.matchAll(/<source src="([^"]+\.mp4)"/g)].map(m => m[1]))];
  const poster = (gallery.match(/poster="([^"]+)"/) || [])[1];
  const thumbRel = r.img;                                   // e.g. ../assets/img/listings/l120-thumb.jpg or posters/l117.jpg
  const card = copy(thumbRel);
  const gallerySaved = images.map(copy).filter(Boolean);
  const videoSaved = withVideos ? videos.map(v => { const s = path.join(host, v.replace(/^(\.\.\/)+/, '')); const n = path.basename(s); if (fs.existsSync(s)) { fs.copyFileSync(s, path.join(outAssets, n)); return n; } return null; }).filter(Boolean) : [];
  const m = r.title.match(/(\d+(?:\.\d+)?)\s*(nali|gaj|sq m)\b/i);
  let size = null, unit = null;
  if (m) { size = Number(m[1]); unit = m[2].toLowerCase() === 'sq m' ? 'sqm' : m[2].toLowerCase(); }
  else if (r.nali) { size = r.nali; unit = 'nali'; }
  const priceLabel = r.status === 'sold' ? 'Sold' : /enquiry/i.test(r.price) ? 'On enquiry' : r.price;
  out.push({
    id: r.id, slug: r.slug, name: r.title, place: spec.Location || r.area,
    area: AREA[r.areaKey] || 'pauri', type: /hotel/i.test(r.title) ? 'Hotel' : 'Land',
    access: r.access || 'Ask us', status: r.status === 'sold' ? 'Sold' : 'Available',
    size, unit, rate: r.rate ?? null, rateUnit: 'sqft', total: r.total ?? null, priceLabel,
    image: card, images: gallerySaved, videos: videoSaved, hasVideo: videos.length > 0, poster: poster ? copy(poster) : null,
    view: spec.View || 'To confirm', aspect: spec.Aspect || 'To confirm',
    documents: 'Gone through with you before any money moves',
    summary: body[0] || '', body, highlights,
    whatsapp: r.wa ? (r.wa.startsWith('http') ? r.wa : 'https://' + r.wa) : null,
  });
}

const header = `/** GENERATED by tools/import-devbhoomi.mjs from the live Devbhoomi Realtors checkout. Do not edit by hand. */\n`;
const body = out.map(o => JSON.stringify(o, null, 1)).join(',\n');
fs.writeFileSync(path.join(root, 'site/real-estate/listings.mjs'),
  `${header}const media = name => new URL(\`./assets/listings/\${name}\`, import.meta.url).href;\nconst resolve = p => ({...p, image: p.image ? media(p.image) : null, images: p.images.map(media), videos: p.videos.map(media), poster: p.poster ? media(p.poster) : null});\nexport const listings = [\n${body}\n].map(resolve);\n`);
// Title and description for every page, copied from the live site's own head tags (they were tuned from Search Console).
const headOf = file => {
  const h = fs.readFileSync(file, 'utf8');
  return { title: decode((h.match(/<title>([\s\S]*?)<\/title>/) || ['', ''])[1].trim()), description: decode((h.match(/<meta name="description" content="([^"]*)"/) || ['', ''])[1].trim()) };
};
const seo = {};
for (const [route, dir] of [['/', ''], ['/properties/', 'properties'], ['/areas/', 'areas'], ['/cottages/', 'cottages'], ['/about/', 'about'], ['/services/', 'services'], ['/guide/', 'guide'], ['/contact/', 'contact'], ['/land-valuation/', 'land-valuation'], ['/privacy/', 'privacy']]) seo[route] = headOf(path.join(host, dir, 'index.html'));
for (const r of records) seo[`/properties/${r.slug}/`] = headOf(path.join(host, 'properties', r.slug, 'index.html'));
fs.writeFileSync(path.join(root, 'site/real-estate/seo-data.mjs'), `/** GENERATED by tools/import-devbhoomi.mjs from the live site's head tags. Do not edit by hand. */\nexport const seo = ${JSON.stringify(seo, null, 1)};\n`);
console.log(`Imported ${out.length} listings, ${copied.size} images${withVideos ? ', videos included' : ''}.`);
